import sys, io
md, hist = sys.argv[1], sys.argv[2]   # CLAUDE.md, CLAUDE-history.md
s = io.open(md, encoding='utf-8').read()
def R(old, new):
    global s
    assert s.count(old) == 1, old[:80]
    s = s.replace(old, new)
R("after editing it run `node tools/precompile.js` (it writes `drills.html`).", "after editing it run `node tools/precompile.js` (it writes `drills.html` and `drills.app.js`).")
R("| **Git** | Pushed up to CU (`b71506b`) on 2026-10-29. CV (`0766ad5`) committed, waiting for her push. |",
  "| **Git** | Pushed up to CU (`b71506b`) on 2026-10-29. CV (`0766ad5`), the CLAUDE.md tidy (`ee9c28e`) and CW committed, waiting for her push. |")
a = s.index("| **App size** |"); b = s.index("\n", a)
s = s[:a] + "| **App size** | 8.2 MB of code (2.2 MB gzipped). Since Build CW (her OK, 2026-10-29) the code is its own file, `drills.app.js`, next to a 34 KB `drills.html` that loads it as `drills.app.js?v=<hash>` (a new hash each build, so a new page never meets an old cached copy). Measured on a copy with a four-times slower CPU: the first screen comes about a third sooner (4.9 s to 3.2 s), a returning student's another third (3.6 s to 2.5 s), because the browser keeps the file and its compiled code. A per-floor split would save little (the books above Beginner are about 14%) for a large rebuild: not now. |" + s[b:]
R("- Push CV.\n", "- Push: CV, the CLAUDE.md tidy and CW.\n")
a = s.index("- Two open calls on the board:"); b = s.index("\n", a)
s = s[:a] + "- Nothing open on the board right now. The two-week freeze: her OK (2026-10-29) to no full stop, the Prelim books after the trial starts. The app code in its own file: built (CW)." + s[b:]
R("1. The app code in its own file, on her OK.\n2. The Beginner floor's two checkpoints on paper", "1. The Beginner floor's two checkpoints on paper")
R("3. The Prelim floor's Lesson Books, fun first, once the trial has started.", "2. The Prelim floor's Lesson Books, fun first, once the trial has started.")
a = s.index("| `drills.html` | **The page the site serves.**"); b = s.index("\n", a)
s = s[:a] + "| `drills.html` | **The page the site serves.** Since Build CW (2026-10-29) a 34 KB shell: the same page with no babel-standalone, which loads the compiled code with `<script id=\"app-js\" src=\"drills.app.js?v=<hash>\">`. Starts with a `GENERATED by precompile.js` comment. |\n| `drills.app.js` | **The compiled app code** (about 8 MB), written by precompile.js next to the page (named after it: `drills.html` -> `drills.app.js`). Its own file so the browser keeps it, and its compiled code, between visits and reads it while it downloads. Never edit it by hand. |" + s[b:]
R("reads `drills.src.html` and writes `drills.html`. Uses", "reads `drills.src.html` and writes `drills.html` and `drills.app.js` (the hash in `?v=` is the code's). Uses")
R("**Rule: edit `drills.src.html`, then run `node tools/precompile.js`, then commit BOTH files.**", "**Rule: edit `drills.src.html`, then run `node tools/precompile.js`, then commit all three: `drills.src.html`, `drills.html` and `drills.app.js`.**")
io.open(md, 'w', encoding='utf-8').write(s)
h = io.open(hist, encoding='utf-8').read().split('\n')
idx = [i for i, l in enumerate(h) if l.startswith('| 741 |')]
assert len(idx) == 1 and not any(l.startswith('| 742 |') for l in h)
h[idx[0] + 1:idx[0] + 1] = ["| 742 | 2026-10-29 | **The app code in its own file (Build CW; her OK at 17:59 to the measured proposal).** Measured first: drills.html was 8.2 MB (2.2 MB gzipped); first screen 0.9 s on a desktop, about 4 s with the CPU four times slower, about 9 s on a slow phone and network, three quarters of it the browser reading the code (6,166 small top-level parts; minifying saves nothing; the books above Beginner are about 14%). precompile.js (tools/ and the workspace copy) now writes the page and, next to it, its code: drills.html (34 KB) loads `<script id=\"app-js\" src=\"drills.app.js?v=<md5 of the code, 10 hex>\">`; the code file starts with a GENERATED comment. On a copy at CPU x4 and good wifi: first screen 4.9 s -> 3.2 s; return visits 3.6 s -> 2.5 s (the browser keeps the file and its compiled code). No change to what anyone sees. Tests: the harness and err745.js serve `*.app.js` next to the page; 59 chapters, the books, the online books, cv771, house771 and the regression on the two-file build. Also this day: CLAUDE.md tidied (ee9c28e): Current Status of 29 Oct and the standing rules stay in CLAUDE.md, the rest moved here. |"]
io.open(hist, 'w', encoding='utf-8').write('\n'.join(h))
print('CLAUDE.md and CLAUDE-history.md updated (row 742)')
